.button-base {
  padding: 0.5rem 1rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  border: none;
}

.button-danger {
  @extend .button-base;
  background-color: #ef4444;
  color: #ffffff;
}

// Placeholder selector: NOT emitted into final compiled CSS on its own!
%card-layout {
  background-color: #ffffff;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
  padding: 1.5rem;
}

.profile-widget {
  @extend %card-layout;
}

.analytics-widget {
  @extend %card-layout;
}

%bordered-box {
  border: 1px solid #e2e8f0;
}

%rounded-pill {
  border-radius: 9999px;
}

%flex-row {
  display: flex;
  align-items: center;
}

.interactive-tag {
  @extend %bordered-box;
  @extend %rounded-pill;
  @extend %flex-row;

  padding: 0.25rem 0.75rem;
  background-color: #f8fafc;
}

%pill-style {
  border-radius: 50px;
}

// INVALID / FORBIDDEN IN SASS:
@media (min-width: 768px) {
  .desktop-button {
    // Compile Error: You may not @extend an outer selector from within @media!
    // @extend %pill-style;
  }
}

// Workaround: Use a mixin instead when media query boundaries are involved
@mixin pill-mixin {
  border-radius: 50px;
}

@media (min-width: 768px) {
  .desktop-button {
    @include pill-mixin; // Works reliably!
  }
}
